code.source:
#include <iostream>
using namespace std;

int main() {
    int a[3] = {10, 20, 30};
    char* first = reinterpret_cast<char*>(&a[0]);
    char* second = reinterpret_cast<char*>(&a[1]);
    cout << (second - first) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << sizeof(char) << endl;
    cout << sizeof(int) << endl;
    cout << sizeof(double) << endl;
    cout << sizeof(int*) << endl;
    return 0;
}

